+          !load->isBeforeInBlock(store))
+        return false;
+    }
+    for (triton::StoreOp other : llvm::drop_begin(stores, index + 1)) {
+      if (store.getPtr() != other.getPtr() &&
+          aliases.classify(store.getPtr(), other.getPtr()) !=
+              EntryArgPointerRelation::DistinctEntryRoots)
+        return false;
+    }
+  }
