+      : owner(owner), builder(owner.getContext()) {}
+  ComponentInfo constant(Type type, const llvm::APInt &value) {
+    auto scalar = pd::getElementTypeOrSelf(type);
+    auto attr = builder.getIntegerAttr(scalar, value);
+    OpFoldResult concrete = attr;
+    if (auto tensor = dyn_cast<RankedTensorType>(type))
+      concrete = DenseElementsAttr::get(tensor, attr);
+    // Zero needs no identity; other constants remain distinct components.
+    return {type,
+            value.isZero() ? ComponentIdentity{}
+                           : ComponentIdentity{owner, nextField++},
+            concrete,
+            {}};
+  }
+  ComponentInfo constant(Type type, int64_t value) {
+    auto width = pd::getIntegerWidth(type);
+    assert(succeeded(width));
+    return constant(type, llvm::APInt(*width, value, true));
+  }
+  FailureOr<llvm::APInt> constantValue(const ComponentInfo &info) {
+    auto width = pd::getIntegerWidth(info.type);
