+  info.terms.origin = *origin;
+  info.terms.irregular = *irregular;
+  for (unsigned i = 0; i < info.terms.coefficients.size(); ++i) {
+    auto coefficient = math.add(lhs.terms.coefficients[i],
+                                rhs.terms.coefficients[i], subtract);
+    if (failed(coefficient))
+      return failure();
+    info.terms.coefficients[i] = *coefficient;
+  }
+  auto full = math.add(lhs.fullOffsets, rhs.fullOffsets, subtract);
+  if (failed(full))
+    return failure();
+  info.fullOffsets = *full;
+  return info;
+}
+FailureOr<SymbolicOffsetInfo> shapeOffset(const SymbolicOffsetInfo &source,
+                                          Type type,
+                                          ComponentExpression::Kind kind,
+                                          unsigned axis,
+                                          SymbolicArithmetic &math) {
+  auto info = source;
