+  ASSERT_TRUE(module);
+  auto f = *module->getOps<FuncOp>().begin();
+  Value zero = *f.getBody().front().getOps<arith::ConstantOp>().begin();
+  SmallVector<Value> unchanged, zeros;
+  SmallVector<AddPtrOp> ptrs;
+  f.walk([&](Operation *op) {
