+      unchanged.push_back(op->getResult(0));
+    if (isa<arith::MulIOp, arith::IndexCastOp, arith::IndexCastUIOp>(op))
+      zeros.push_back(op->getResult(0));
+    if (auto add = dyn_cast<AddPtrOp>(op))
+      ptrs.push_back(add);
