+      tt.func @reductions(%rows:tensor<2xi32>, %cols:tensor<4xi32>) {
+        %e = tt.expand_dims %rows {axis=1:i32} : tensor<2xi32> -> tensor<2x1xi32>
+        %b = tt.broadcast %e : tensor<2x1xi32> -> tensor<2x4xi32>
