+        %middle = "tt.reduce"(%b3) ({
+        ^bb0(%x:i32, %y:i32):
+          %s = arith.maxsi %x,%y : i32
+          tt.reduce.return %s : i32
+        }) {axis=1:i32,tag="middle"} : (tensor<2x4x8xi32>) -> tensor<2x8xi32>
+        %scalar = "tt.reduce"(%cols) ({
