+      %reverse = arith.subi %three, %r : tensor<4xi32>
+      %descending = arith.extui %reverse : tensor<4xi32> to tensor<4xi64>
+      %opaque = arith.extui %unknown : tensor<4xi32> to tensor<4xi64>
+      tt.return
+    } }
