+bool isIndex(OpFoldResult value) {
+  if (auto ssa = dyn_cast<Value>(value))
+    return ssa.getType().isIndex();
+  if (auto attr = dyn_cast<Attribute>(value))
+    return isa<TypedAttr>(attr) && cast<TypedAttr>(attr).getType().isIndex();
+  return false;
+}
