+#define TRITON_PTR_ANALYSIS_TEST_UTILS_H
+
+#include "TritonMemoryAccess/PtrAnalysisRules/CommonPtrRules.h"
+#include "mlir/Dialect/Arith/IR/Arith.h"
+#include "mlir/Dialect/Tensor/IR/Tensor.h"
